import { IconEdit, IconChatbot, IconPerson } from "@airbus/icons";
import { focus, svgColor, svgUri } from "../../helpers";
import { StyleFn } from "..";

export const Avatar: StyleFn = (theme, mode) => {
  const { color, size } = theme;
  const { focusWithPseudo } = focus(theme, mode);

  const statusStyles = {
    content: '""',
    display: "block",
    position: "absolute",
    right: "6%",
    bottom: "6%",
    minWidth: "22%",
    minHeight: "22%",
    border: `1.5px solid ${color.border.neutral.minimal[mode]}`,
    borderRadius: "50%",
  };
  const hoverColor = color.saturated.skyblue[mode];
  const activeColor = color.surface.accent.default[mode];
  const iconColor = color.text.accent.corporate[mode];

  const focusOffset = (offset: number) => {
    const base = -offset; // the focus ring has to be offset by the border width
    const enhanced = -offset - 8; // the focus ring has to be offset by the border width + the hover/active box shadow

    return {
      "&:focus-visible:before": {
        top: base,
        left: base,
        right: base,
        bottom: base,
      },
      "&:hover:focus-visible:before, &:active:focus-visible:before": {
        top: enhanced,
        left: enhanced,
        right: enhanced,
        bottom: enhanced,
      },
    };
  };

  return {
    root: {
      extend: [focusWithPseudo({ radius: "50%", pseudo: "before" })],
      ...focusOffset(3),
      border: `3px solid transparent`,
      display: "flex",
      width: "1em",
      height: "1em",
      fontSize: size.spacing[48],
      alignItems: "center",
      justifyContent: "center",
      flexShrink: 0,
      borderRadius: "50%",
      position: "relative",
      "&:hover:not($_editable)": {
        borderColor: hoverColor,
        boxShadow: `0 0 0 4px ${hoverColor}`,
      },
      "&:active:not($_editable)": {
        borderColor: activeColor,
        boxShadow: `0 0 0 4px ${activeColor}`,
      },
    },
    img: {
      width: "100%",
      height: "100%",
      borderRadius: "50%",
    },
    _editable: {
      position: "relative",
      cursor: "pointer",
      "&:hover:after": {
        content: '""',
        borderRadius: "50%",
        // percentage is applied to background size to scale with increase in fontsize
        position: "absolute",
        width: "114%",
        height: "114%",
        opacity: 0.8,
        backgroundColor: color.surface.accent.corporate[mode],
        backgroundImage: svgUri(svgColor(IconEdit.data, "#fff")),
        backgroundPosition: "center center",
        backgroundRepeat: "no-repeat",
        backgroundSize: "56%",
      },
    },
    _none: {
      borderRadius: "50%",
      backgroundColor: color.surface.componentonbackground.strong[mode],
      backgroundImage: svgUri(svgColor(IconPerson.data, iconColor)),
      backgroundPosition: "center center",
      backgroundRepeat: "no-repeat",
      backgroundSize: "88%",
    },
    _chatbot: {
      borderRadius: "50%",
      backgroundColor: color.surface.componentonbackground.strong[mode],
      backgroundImage: svgUri(svgColor(IconChatbot.data, iconColor)),
      backgroundPosition: "center center",
      backgroundRepeat: "no-repeat",
      backgroundSize: "88%",
    },
    _notDisturb: {
      "&:after": {
        extend: [statusStyles],
        backgroundColor: color.surface.feedback.error.default[mode],
      },
    },
    _away: {
      "&:after": {
        extend: [statusStyles],
        backgroundColor: color.surface.feedback.warning.default[mode],
      },
    },
    _offline: {
      "&:after": {
        extend: [statusStyles],
        backgroundColor: color.palette.coolgrey["50"],
      },
    },
    _online: {
      "&:after": {
        extend: [statusStyles],
        backgroundColor: color.surface.feedback.success.default[mode],
      },
    },
    _xsmall: {
      fontSize: size.spacing[24],
      borderWidth: 1,
      "&:after": { borderWidth: 1 },
      ...focusOffset(1),
    },
    _small: {
      fontSize: size.spacing[32],
      borderWidth: 2,
      "&:after": { borderWidth: 1 },
      ...focusOffset(2),
    },
    _medium: {},
    _large: {
      fontSize: size.spacing[64],
      borderWidth: 4,
      "&:after": { borderWidth: 1.75 },
      ...focusOffset(4),
    },
    _xlarge: {
      fontSize: size.spacing[80],
      borderWidth: 5,
      "&:after": { borderWidth: 2 },
      ...focusOffset(5),
    },
    _xxlarge: {
      fontSize: size.spacing[112],
      borderWidth: 6,
      "&:after": { borderWidth: 2.5 },
      ...focusOffset(6),
    },
  };
};
